package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(r, &n)
	var s int64
	for i := 0; i < n; i++ {
		var x int64
		fmt.Fscan(r, &x)
		s += x
	}
	fmt.Println(s)
	if s%2 == 0 {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

