{
    static void Main()
    {
        var data = Console.In.ReadToEnd().Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        int n = int.Parse(data[0]);
        long s = data.Skip(1).Take(n).Sum(long.Parse);
        Console.WriteLine(s);
        Console.WriteLine(s % 2 == 0 ? "YES" : "NO");
    }
